{
    "schemaVersion":  1,
    "weenieClassId":  42047186,
    "mutators":  [
                     "shaman",
                     "enchanter",
                     "warder"
                 ],
    "rules":  [
                  {
                      "id":  "phase_01_release_inhibitions",
                      "trigger":  "combat_start",
                      "thresholdPercent":  0,
                      "intervalSeconds":  0,
                      "chancePercent":  100,
                      "minPlayers":  1,
                      "once":  true,
                      "actions":  [
                                      {
                                          "type":  "set_phase",
                                          "phase":  "phase_01_release"
                                      },
                                      {
                                          "type":  "say",
                                          "text":  "I WILL CAST RELEASE YOUR INHIBITIONS!"
                                      },
                                      {
                                          "type":  "effect",
                                          "effect":  "PortalStorm"
                                      },
                                      {
                                          "type":  "taunt",
                                          "channel":  "fellowship",
                                          "text":  "[%b] The air loosens around you. Feet, vows, and good sense become optional."
                                      }
                                  ]
                  },
                  {
                      "id":  "phase_02_open_window",
                      "trigger":  "health_below",
                      "thresholdPercent":  85,
                      "intervalSeconds":  0,
                      "chancePercent":  100,
                      "minPlayers":  1,
                      "once":  true,
                      "actions":  [
                                      {
                                          "type":  "set_phase",
                                          "phase":  "phase_02_open_window"
                                      },
                                      {
                                          "type":  "say",
                                          "text":  "Open the shutters of your little souls. Let the weather in."
                                      },
                                      {
                                          "type":  "scatter",
                                          "target":  "all",
                                          "distance":  18
                                      },
                                      {
                                          "type":  "effect",
                                          "effect":  "BreatheLightning"
                                      }
                                  ]
                  },
                  {
                      "id":  "phase_03_skin_rain",
                      "trigger":  "health_below",
                      "thresholdPercent":  70,
                      "intervalSeconds":  0,
                      "chancePercent":  100,
                      "minPlayers":  1,
                      "once":  true,
                      "actions":  [
                                      {
                                          "type":  "set_phase",
                                          "phase":  "phase_03_skin_rain"
                                      },
                                      {
                                          "type":  "taunt",
                                          "channel":  "local",
                                          "text":  "Feel the rain remember you, %t."
                                      },
                                      {
                                          "type":  "knock_up",
                                          "target":  "all",
                                          "distance":  20
                                      },
                                      {
                                          "type":  "effect",
                                          "effect":  "BreatheFrost"
                                      }
                                  ]
                  },
                  {
                      "id":  "phase_04_unwritten_path",
                      "trigger":  "health_below",
                      "thresholdPercent":  55,
                      "intervalSeconds":  0,
                      "chancePercent":  100,
                      "minPlayers":  1,
                      "once":  true,
                      "actions":  [
                                      {
                                          "type":  "set_phase",
                                          "phase":  "phase_04_unwritten_path"
                                      },
                                      {
                                          "type":  "say",
                                          "text":  "No map, no margin, no mercy. Write your next step while falling."
                                      },
                                      {
                                          "type":  "pull",
                                          "target":  "farthest",
                                          "distance":  24
                                      },
                                      {
                                          "type":  "push",
                                          "target":  "nearest",
                                          "distance":  16
                                      },
                                      {
                                          "type":  "maintain_minions",
                                          "weenieClassId":  7,
                                          "count":  3,
                                          "health":  100
                                      }
                                  ]
                  },
                  {
                      "id":  "phase_05_thunder_chorus",
                      "trigger":  "health_below",
                      "thresholdPercent":  40,
                      "intervalSeconds":  0,
                      "chancePercent":  100,
                      "minPlayers":  1,
                      "once":  true,
                      "actions":  [
                                      {
                                          "type":  "set_phase",
                                          "phase":  "phase_05_thunder_chorus"
                                      },
                                      {
                                          "type":  "taunt",
                                          "channel":  "fellowship",
                                          "text":  "[%b] Sing badly if you must. The thunder will keep time."
                                      },
                                      {
                                          "type":  "scatter",
                                          "target":  "all",
                                          "distance":  24
                                      },
                                      {
                                          "type":  "effect",
                                          "effect":  "EnchantUpBlue"
                                      }
                                  ]
                  },
                  {
                      "id":  "phase_06_blank_page",
                      "trigger":  "health_below",
                      "thresholdPercent":  20,
                      "intervalSeconds":  0,
                      "chancePercent":  100,
                      "minPlayers":  1,
                      "once":  true,
                      "actions":  [
                                      {
                                          "type":  "set_phase",
                                          "phase":  "phase_06_blank_page"
                                      },
                                      {
                                          "type":  "say",
                                          "text":  "The page is blank because I ate the ink."
                                      },
                                      {
                                          "type":  "blink",
                                          "target":  "random",
                                          "distance":  28
                                      },
                                      {
                                          "type":  "knock_up",
                                          "target":  "all",
                                          "distance":  26
                                      },
                                      {
                                          "type":  "effect",
                                          "effect":  "TransUpWhite"
                                      }
                                  ]
                  },
                  {
                      "id":  "storm_rhythm_phase_03",
                      "trigger":  "timer",
                      "thresholdPercent":  0,
                      "intervalSeconds":  18,
                      "chancePercent":  65,
                      "minPlayers":  1,
                      "once":  false,
                      "phase":  "phase_03_skin_rain",
                      "actions":  [
                                      {
                                          "type":  "taunt",
                                          "channel":  "local",
                                          "text":  "Drop by drop, %t. Drop by drop."
                                      },
                                      {
                                          "type":  "scatter",
                                          "target":  "random",
                                          "distance":  12
                                      },
                                      {
                                          "type":  "effect",
                                          "effect":  "BreatheFrost"
                                      }
                                  ]
                  },
                  {
                      "id":  "thunder_rhythm_phase_05",
                      "trigger":  "timer",
                      "thresholdPercent":  0,
                      "intervalSeconds":  14,
                      "chancePercent":  75,
                      "minPlayers":  1,
                      "once":  false,
                      "phase":  "phase_05_thunder_chorus",
                      "actions":  [
                                      {
                                          "type":  "taunt",
                                          "channel":  "fellowship",
                                          "text":  "[%b] The chorus chooses %t for the high note."
                                      },
                                      {
                                          "type":  "push",
                                          "target":  "trigger",
                                          "distance":  20
                                      },
                                      {
                                          "type":  "effect",
                                          "effect":  "BreatheLightning"
                                      }
                                  ]
                  },
                  {
                      "id":  "resist_stomp",
                      "trigger":  "spell_resisted",
                      "thresholdPercent":  0,
                      "intervalSeconds":  0,
                      "chancePercent":  45,
                      "minPlayers":  1,
                      "once":  true,
                      "actions":  [
                                      {
                                          "type":  "taunt",
                                          "channel":  "local",
                                          "text":  "Your spell bounced. You may follow it."
                                      },
                                      {
                                          "type":  "knock_up",
                                          "target":  "trigger",
                                          "distance":  32
                                      },
                                      {
                                          "type":  "effect",
                                          "effect":  "LayingofHands"
                                      }
                                  ]
                  },
                  {
                      "id":  "death_last_note",
                      "trigger":  "death",
                      "thresholdPercent":  0,
                      "intervalSeconds":  0,
                      "chancePercent":  100,
                      "minPlayers":  1,
                      "once":  true,
                      "actions":  [
                                      {
                                          "type":  "say",
                                          "text":  "Fine. Keep the sky. I was finished with it."
                                      },
                                      {
                                          "type":  "effect",
                                          "effect":  "TransDownBlack"
                                      }
                                  ]
                  }
              ]
}

